from pathlib import Path
import json,sys,hashlib,datetime
import fitz
from PIL import Image
R=Path(__file__).resolve().parents[3];sys.path.insert(0,str(R/'scripts'));from validate import canonical_json,question_hash
snap=json.loads((R/'audits/question-visual-review/lead/stage-L23-L25.json').read_text());current=json.loads((R/'data/question-visuals/manifest.json').read_text());records={r['questionId']:r for r in current['records']};assets={a['id']:a for a in current['assets']};by={q['id']:q for q in json.loads((R/'data/bank.json').read_text())['questions']}
sha=lambda v:hashlib.sha256(canonical_json(v).encode()).hexdigest()
raw=R/'sources/raw/AI_for_Robotics_All_Lectures.pdf';sourcehash=hashlib.sha256(raw.read_bytes()).hexdigest();doc=fitz.open(raw)
exclude={'W05-L23-Q045':'Needs control_torque definition from p0717 as well.','W05-L23-Q050':'Check source time-axis labels at lower plot edge.','W05-L24-P0738-Q01':'Bottom comparator signs clipped.','W05-L24-P0738-Q03':'Bottom comparator signs clipped.','W05-L24-P0746-Q05':'Integral lower limit and candidate fraction edge clipped.','W05-L24-P0747-Q02':'Integral lower limit and candidate fraction edge clipped.','W05-L24-P0747-Q04':'Integral lower limit and candidate fraction edge clipped.','W05-L25-Q038':'Lowest comparator signs clipped.','W05-L25-Q049':'Lowest comparator signs clipped.'}
notes={703:'Exact cubic input law visible without scaling answer.',705:'Input cubic plant/controller definitions visible; no evaluated numeric force.',706:'Full compensation signal paths and summing signs visible.',712:'Pendulum horizontal angle reference, positive torque and gravity directions visible.',713:'Actual pendulum plant model and physical term meanings visible without solved beta.',715:'Full inertia scaling and additive compensation topology visible.',716:'Desired-state tuple ordering, function body and parameter declarations intact.',717:'Full controller state, error sign, torque expression and return tuple intact; no computed requested numeric results.',718:'Full plant function and solver call visible.',719:'Pending lower plot-edge check.',720:'Phase portrait axes with angle/rate units visible.',730:'Partition and plant input definitions visible, without uncertainty residual solution.',731:'Full computed-torque topology and signs plus exact error definition visible.',734:'Both model-based and desired-state feedforward architectures and their feedback paths intact.',737:'Red background ellipse, enclosed blocks and actual-state paths fully visible.',738:'Pending comparator correction.',739:'Actual plant and estimated controller alpha/beta definitions intact; solved error residual excluded.',741:'Complete PID/encoder negative feedback diagram.',744:'Unforced spring-damper equation and energy candidate only; derivative result and computed values excluded.',746:'Pending candidate edge correction.',755:'Full Cartesian-reference to joint-reference conversion and torque path.',757:'Full forward-kinematics actual feedback path and error comparator signs.',761:'Full Cartesian gain, virtual force and transpose-Jacobian block order.',763:'Complete base and tool axis labels, origins and schematic sphere geometry.',765:'Pending comparator correction.',769:'Pending comparator correction.'}
checks={};out=[];held=[]
for old in snap['records']:
 qid=old['questionId']
 if qid in exclude:held.append({'questionId':qid,'reason':exclude[qid]});continue
 r=records[qid];assert r==old,(qid,'changed record needs reinspection')
 for aid in r['assetIds']:
  if aid in checks:continue
  a=assets[aid];assert a['sourceSha256']==sourcehash
  p=R/a['path'];assert hashlib.sha256(p.read_bytes()).hexdigest()==a['sha256']
  pix=doc[a['physicalPage']-1].get_pixmap(matrix=fitz.Matrix(a['renderDpi']/72,a['renderDpi']/72),clip=fitz.Rect(a['cropRectangle']),alpha=False)
  im=Image.open(p).convert('RGB');assert im.size==(pix.width,pix.height)==(a['width'],a['height']);assert im.tobytes()==pix.samples,(qid,'pixel mismatch')
  checks[aid]={'assetSha256':a['sha256'],'assetMetadataSha256':sha(a),'originalPdfSha256':sourcehash,'physicalPage':a['physicalPage'],'rasterMatchesIndependentPdfRender':True,'visualInspection':notes[a['physicalPage']]}
 q=by[qid];assert question_hash(q)==r['questionSha256'];h=sha(r)
 out.append({'id':f'QVR-{qid}-lead-crop-{h[:12]}','visualId':r['id'],'visualVersion':r['version'],'visualSha256':h,'reviewerId':'independent-input-reviewer-integration-L20-L35','decision':'verified','questionId':qid,'questionVersion':q['version'],'questionSha256':question_hash(q),'sourceVersions':{s['sourceId']:s['sourceSha256'] for s in r['sourceRefs']},'assetHashes':{aid:assets[aid]['sha256'] for aid in r['assetIds']},'assetMetadataHashes':{aid:sha(assets[aid]) for aid in r['assetIds']},'reviewedAssetIds':r['assetIds'],'displayRole':'question_input','checks':dict.fromkeys(['inventoryCompleteness','requiredInputFidelity','legibility','noAnswerLeak','sourceLinkage'],True),'reviewedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reasoning':' '.join(dict.fromkeys(notes[assets[aid]['physicalPage']] for aid in r['assetIds'])),'scope':'Full current question stem, choices and assumptions independently read; every actual PNG independently visually inspected at readable scale. Raster pixels independently rerendered from hash-verified source PDF and matched exactly. This approves the pre-answer input role only, not browser display or a new answer judgment. Input labels/formulas/code are legitimate premises; worked numeric outputs and answer keys are excluded.','evidencePath':'audits/question-visual-review/lead/L23-L25-pixel-inspection.json','findings':[]})
p=R/'data/question-visuals/reviews/L23-L25-required-lead-first.json';assert not p.exists();p.write_text(json.dumps(out,indent=2)+'\n')
(R/'audits/question-visual-review/lead/L23-L25-pixel-inspection.json').write_text(json.dumps({'sourceSha256':sourcehash,'assets':checks,'approvedQuestionIds':[r['questionId'] for r in out],'held':held},indent=2)+'\n')
print(json.dumps({'approvedRequiredRecords':len(out),'independentlyComparedAssets':len(checks),'held':held}))
